import os, sys, select, subprocess, fcntl, termios, struct, time, json
def run(argv, resp, env_over=None, timeout=5.0):
    m, s = os.openpty()
    fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack('HHHH', 24, 80, 0, 0))
    e = dict(os.environ); e.pop('NO_COLOR', None); e['TERM']='xterm-256color'
    if env_over:
        for k,v in env_over.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    p = subprocess.Popen(argv, stdin=s, stdout=s, stderr=s, env=e, close_fds=True)
    os.close(s)
    out=b''; answered=False
    dl=time.time()+timeout
    while time.time()<dl:
        r,_,_=select.select([m],[],[],0.2)
        if r:
            try: d=os.read(m,65536)
            except OSError: break
            if not d: break
            out+=d
        if not answered and b'\x1b[c' in out:
            os.write(m, resp.encode()); answered=True
        if p.poll() is not None:
            time.sleep(0.1)
            while True:
                r,_,_=select.select([m],[],[],0.1)
                if not r: break
                try: d=os.read(m,65536)
                except OSError: break
                if not d: break
                out+=d
            break
    if p.poll() is None: p.kill()
    p.wait(); os.close(m)
    return p.returncode, out
if __name__=='__main__':
    cfg=json.loads(sys.argv[1])
    rc,out=run(cfg['argv'], cfg['resp'], cfg.get('env'))
    sys.stdout.write('RC=%s TTY=%r\n'%(rc,out))
